/**
 * Magic-link landing page — /magic/:token. Redeems the token on mount via
 * AuthContext's loginWithMagicLink (POST /api/auth/magic-login), which
 * turns it into a normal session, then routes the person to whatever
 * dashboard fits their role. No SMTP involved: this link was generated by
 * an admin pressing a button (AdminPage's MagicLinkPanel) and handed to the
 * driver manually (text/email) — see routers/admin.py's magic-link endpoint.
 */
import React, { useEffect, useRef, useState } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useAuth } from '../context/AuthContext.jsx'
import Footer from '../components/Footer.jsx'

function homeFor(role) {
  if (role === 'driver') return '/driver'
  if (role === 'supplier') return '/supplier'
  if (role === 'admin') return '/admin'
  return '/'
}

export default function MagicLoginPage() {
  const { token } = useParams()
  const { loginWithMagicLink } = useAuth()
  const navigate = useNavigate()
  const [error, setError] = useState(null)
  const attempted = useRef(false)

  useEffect(() => {
    if (attempted.current) return
    attempted.current = true
    ;(async () => {
      try {
        const user = await loginWithMagicLink(token)
        navigate(homeFor(user.role), { replace: true })
      } catch (e) {
        setError(e.message || 'This link is invalid, expired, or already used.')
      }
    })()
  }, [token, loginWithMagicLink, navigate])

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column', background: 'var(--brand-bg, #0f1117)' }}>
      <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20 }}>
        <div style={{
          width: 360, background: 'var(--brand-surface-2, #161b27)', border: '1px solid var(--brand-border-soft, #1e2130)', borderRadius: 16,
          padding: 32, textAlign: 'center', color: 'var(--brand-text, #e2e8f0)',
        }}>
          {!error ? (
            <>
              <div style={{ fontSize: 18, fontWeight: 800, marginBottom: 8 }}>Signing you in…</div>
              <div style={{ fontSize: 12, color: 'var(--brand-text-dimmer, #64748b)' }}>One moment.</div>
            </>
          ) : (
            <>
              <div style={{ fontSize: 18, fontWeight: 800, marginBottom: 8, color: 'var(--brand-danger-text, #fca5a5)' }}>Link didn't work</div>
              <div style={{ fontSize: 13, color: 'var(--brand-text-dim, #94a3b8)', marginBottom: 16 }}>{error}</div>
              <button onClick={() => navigate('/login')} style={{
                background: 'linear-gradient(135deg,#3b82f6,#6366f1)', border: 'none', borderRadius: 10,
                padding: '10px 18px', color: '#fff', fontWeight: 700, fontSize: 13, cursor: 'pointer',
              }}>Go to sign in</button>
            </>
          )}
        </div>
      </div>
      <Footer />
    </div>
  )
}
